from org.uacalc.terms import Terms, NonVariableTerm, VariableImp, Variable
from org.uacalc.alg.op import OperationSymbol
from org.uacalc.io import AlgebraIO

def _map(*pairs):
    try:
        from java.util import HashMap
        m = HashMap()
        for k, v in pairs:
            m.put(k, v)
        return m
    except ImportError:
        return dict(pairs)

def _wsb(term, prefix=""):
    try:
        from java.lang import StringBuffer
        sb = StringBuffer(prefix)
        term.writeStringBuffer(sb)
        return sb.toString()
    except ImportError:
        return term.writeStringBuffer(prefix)

def _names(lst):
    if lst is None:
        return None
    out = []
    for v in list(lst):
        getter = getattr(v, "getName", None)
        if getter is not None:
            out.append(getter())
        else:
            out.append(str(v))
    return ",".join(out)

def _syms(coll):
    if coll is None:
        return None
    parts = sorted([x.name() + "/" + str(int(x.arity())) for x in list(coll)])
    return ",".join(parts)

def _vals(op, n=2):
    ar = int(op.arity())
    iva = op.intValueAt
    if ar == 0:
        return [int(iva([]))]
    if ar == 1:
        return [int(iva([i])) for i in range(n)]
    return [int(iva([i, j])) for i in range(n) for j in range(n)]

def _varlist(*vars):
    try:
        from java.util import ArrayList
        lst = ArrayList()
        for v in vars:
            lst.add(v)
        return lst
    except ImportError:
        return list(vars)

c2 = AlgebraIO.readAlgebraFile("resources/algebras/cyclic2.ua")
